public Flux<Data> getData() {
    // 這裡定義了一個會呼叫外部 API 的 Flux
    Flux<Data> flux = webClient.get().uri("/data").retrieve().bodyToFlux(Data.class);

    // 開發者為了除錯，先訂閱一次印出 Log
    flux.subscribe(data -> log.info("Data: " + data));

    // 然後將同一個 Flux 回傳給 Controller 供前端使用
    return flux;
}
